<?php
namespace App\Interfaces\Http\Controllers\Api\V1\Compliance;use App\Application\Audit\AuditWriter;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
final class ComplianceController{
public function grantAccess(Request$r,AuditWriter$audit){$d=$r->validate(['user_id'=>'required|uuid|exists:users,id','tenant_id'=>'required|uuid|exists:tenants,id','purpose'=>'required|string|max:64','justification'=>'required|string|min:40|max:4000','starts_at'=>'required|date','expires_at'=>'required|date|after:starts_at']);abort_if($d['user_id']===$r->user()->id,403,'Users cannot approve their own privileged access.');$id=(string)Str::uuid();DB::table('privileged_access_grants')->insert([...$d,'id'=>$id,'approved_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);$audit->record('privileged_access.granted','privileged_access_grant',$id,['user_id'=>$d['user_id'],'tenant_id'=>$d['tenant_id']]);return response()->json(['data'=>['id'=>$id,'expires_at'=>$d['expires_at']]],201);}
public function dataRequest(Request$r,AuditWriter$audit){$d=$r->validate(['party_id'=>'required|uuid|exists:parties,id','type'=>'required|in:ACCESS,CORRECTION,DELETION,RESTRICTION,PORTABILITY,OBJECTION']);$id=(string)Str::uuid();$number='DSR-'.now()->format('Ym').'-'.strtoupper(Str::random(8));DB::table('data_subject_requests')->insert(['id'=>$id,'party_id'=>$d['party_id'],'request_number'=>$number,'type'=>$d['type'],'status'=>'RECEIVED','due_on'=>now()->addDays(30)->toDateString(),'created_at'=>now(),'updated_at'=>now()]);$audit->record('data_subject_request.received','data_subject_request',$id,['type'=>$d['type']]);return response()->json(['data'=>['id'=>$id,'request_number'=>$number,'status'=>'RECEIVED']],201);}
public function audit(Request$r){$q=DB::table('audit_log')->orderByDesc('sequence');if($r->filled('subject_type'))$q->where('subject_type',$r->string('subject_type'));if($r->filled('actor_id'))$q->where('actor_id',$r->string('actor_id'));if(!$r->user()?->hasPermission('cases.str.view'))\App\Application\Compliance\Aml\Str\TippingOffGuard::hideFromAudit($q);return response()->json(['data'=>$q->paginate(min($r->integer('per_page',50),100))]);}}
